#include <string>
#include <vector>

class Formatter {
public:
    std::string format(double value) const;   // e.g. "12.50".
    void set_locale(const std::string& loc);
    void reset_buffer();
};

// Composition: Report HAS a Formatter.
class Report {
public:
    void add(double v) { values_.push_back(v); }
    std::string render() const {
        std::string out;
        for (double v : values_) out += fmt_.format(v) + '\n';   // delegate.
        return out;
    }
private:
    Formatter fmt_;                 // owned component, hidden from callers.
    std::vector<double> values_;
};
// Report exposes add and render only; set_locale and reset_buffer stay private details.
